// Knowledge base about RudraAI — extend this with your actual docs
const kb = [
  { topic: 'services', content: 'RudraAI builds n8n automation workflows, AI agents, lead qualification systems, CRM integrations, email sequences, and client onboarding automations.' },
  { topic: 'pricing', content: '1 automation: $50. 3 automations: $100. 5 automations: $200. More than 5: contact us. All projects include 48-hour deployment and 30-day support.' },
  { topic: 'process', content: 'Our process: 1) Free audit call to map your workflows. 2) We design the n8n automation. 3) 48-hour deployment. 4) 30-day post-launch support. 5) Optional monthly retainer.' },
  { topic: 'tools', content: 'We use n8n for workflows, OpenRouter for AI (Claude, GPT-4, Llama), Notion for knowledge management, and integrate with 400+ tools including Slack, Gmail, HubSpot, Airtable, Cal.com.' },
  { topic: 'timeline', content: 'Most automations are live within 48 hours. Complex multi-system integrations may take 5-7 business days.' },
  { topic: 'booking', content: 'Book a free 60-minute automation audit at rudraai.io/booking. No sales pressure — just a practical look at your workflows.' }
];

const query = ($input.first().json.body ?? $input.first().json).message || '';

// Simple keyword match for context retrieval
const relevant = kb
  .filter(k => {
    const q = query.toLowerCase();
    return q.includes(k.topic) || k.content.toLowerCase().split(' ').some(w => q.includes(w) && w.length > 4);
  })
  .map(k => k.content)
  .join(' ');

const context = relevant || kb.map(k => k.content).join(' ');
return [{ json: { query, context } }];

const orResp = $('RAG Answer (OpenRouter)').first().json;
const olResp = $('RAG Answer (Ollama Fallback)').first().json;
let answer = 'I could not find an answer. Please email hello@rudraai.io.';
try {
  if (orResp && orResp.choices && orResp.choices[0]) {
    answer = orResp.choices[0].message.content;
  } else if (olResp && olResp.message) {
    answer = olResp.message.content;
  }
} catch (e) {}
return [{ json: { answer } }];
